import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),s={name:"guide/configuration.md"};function n(r,e,i,c,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>AsyncUp is configured in two layers:</p><ol><li><strong>Bootstrap</strong>: a handful of environment variables (database, port, the operator token, the encryption key). Set once, rarely touched. This page is the one reference for them.</li><li><strong>Everything else</strong>: managed in the <a href="./web-app.html">web app</a> under <strong>Settings</strong> and stored in your database, secrets encrypted (AES-256-GCM via <code>SECRET_KEY</code>). Changes apply immediately, no restart.</li></ol><h2 id="env-vars" tabindex="-1">Environment variables <a class="header-anchor" href="#env-vars" aria-label="Permalink to &quot;Environment variables {#env-vars}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>8080</code></td><td>Webhook, API and web app port</td></tr><tr><td><code>DB_PATH</code></td><td><code>./data/standup.db</code></td><td>SQLite database file (default storage). The Docker image sets <code>/data/standup.db</code></td></tr><tr><td><code>DATABASE_URL</code></td><td><em>(empty)</em></td><td>Bring-your-own PostgreSQL — when set, SQLite is skipped (see <a href="./deployment.html#database-embedded-or-bring-your-own">Deployment reference</a>)</td></tr><tr><td><code>DB_SSL</code></td><td>from URL <code>sslmode</code></td><td>Postgres TLS: <code>require</code> (encrypt, no verify — default for managed DBs), <code>verify-full</code>, or <code>disable</code></td></tr><tr><td><code>DB_SSL_CA</code></td><td><em>(empty)</em></td><td>CA bundle path for <code>DB_SSL=verify-full</code></td></tr><tr><td><code>OPERATOR_TOKEN</code></td><td><em>(empty)</em></td><td>Operator token for the web app and the JSON API — the way in before Google or SAML sign-in works, and break-glass after. Disabled while empty. <code>DASHBOARD_TOKEN</code> is the older name and still works; when both are set, <code>OPERATOR_TOKEN</code> wins, and a blank <code>OPERATOR_TOKEN=</code> falls back to <code>DASHBOARD_TOKEN</code></td></tr><tr><td><code>SECRET_KEY</code></td><td>—</td><td>Encrypts stored secrets; signs sessions and webhooks. Generate with <code>openssl rand -hex 32</code>. Required (except <code>ADAPTER=fake</code>). Back it up separately from the database</td></tr><tr><td><code>ADAPTER</code></td><td><code>google</code></td><td><code>google</code> for production, <code>fake</code> for a console demo</td></tr><tr><td><code>TENANT_ID</code></td><td><code>default</code></td><td>Tenant identifier — leave as is for self-hosted installs</td></tr></tbody></table><p>Changing a variable needs the container recreated, not just restarted: <code>docker compose up -d --force-recreate asyncup</code>.</p><h2 id="app-settings-stored-in-the-database" tabindex="-1">App settings (stored in the database) <a class="header-anchor" href="#app-settings-stored-in-the-database" aria-label="Permalink to &quot;App settings (stored in the database)&quot;">​</a></h2><p>Open <code>https://HOST/app</code> → <strong>Settings</strong>. Each value saves on its own. Secrets are write-only: the UI shows <em>that</em> they&#39;re set (and, for the service account, its email), never the value.</p><table tabindex="0"><thead><tr><th>Where</th><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>General</td><td>Default timezone for new standups</td><td>Assigned to new standups; people can set their own</td></tr><tr><td>General</td><td>Calendar out-of-office</td><td>Mark people away on OOO days. Off by default; turn on once the <a href="./directory.html#calendar-ooo">delegation for the Calendar scope</a> exists</td></tr><tr><td>Google Chat</td><td>Project number (and the events URL)</td><td>The audience incoming events are verified against. For an add-on Chat app both are needed — <a href="./google-chat-setup.html#the-audience-rule">the audience rule</a></td></tr><tr><td>Google Chat</td><td>Service account</td><td>The JSON key used for Chat API calls, group rosters, Directory lookups and Calendar. Empty = <a href="https://cloud.google.com/docs/authentication/application-default-credentials" target="_blank" rel="noreferrer">Application Default Credentials</a> for Chat only</td></tr><tr><td>Google Chat</td><td>Directory through delegation (legacy)</td><td>Optional <em>Workspace admin to act as</em>: moves Directory lookups to domain-wide delegation. Leave it off with the <a href="./directory.html#admin-role">admin role</a>; Calendar out-of-office doesn&#39;t use it. The <em>Client ID for domain-wide delegation</em> shows under Service account</td></tr><tr><td>Sign-in &amp; SSO</td><td>Google sign-in</td><td>OAuth client ID and secret — <a href="./enterprise-sso.html#google-sign-in">Google sign-in</a></td></tr><tr><td>Sign-in &amp; SSO</td><td>SAML single sign-on</td><td>IdP entity ID, SSO URL, certificate, admin attribute (default <code>groups</code>) and admin group (default <code>asyncup-admins</code>) — <a href="./enterprise-sso.html#saml-sign-in">SAML</a></td></tr><tr><td>Sign-in &amp; SSO</td><td>Setup token</td><td>Whether the operator token still signs in. Can only be switched off while Google or SAML works</td></tr><tr><td>MCP server</td><td>Server, default scopes, access tokens</td><td><a href="./mcp.html">Claude Code and MCP</a></td></tr><tr><td>API &amp; tokens</td><td>Machine tokens</td><td>Tick (<code>POST /tick</code>), CSV export (<code>GET /export</code>) and SCIM (<code>/scim/v2</code>) tokens, each shown once</td></tr><tr><td>Danger zone</td><td>Disconnect Google Chat; Delete all standup history</td><td>Both behind a typed confirmation</td></tr></tbody></table><p>Per-standup settings (schedule, questions, mood, people, roster group, escalation, webhook, digest, archive and delete) live on each standup&#39;s <strong>Settings</strong> tab and in the <a href="./commands.html">chat commands</a>.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>All token comparisons are constant-time. ✱ = covered by the shared rate limiter (60 requests a minute per IP).</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Auth</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /healthz</code></td><td>none</td><td>Liveness: pings the database</td></tr><tr><td><code>GET /health/chat</code></td><td>none</td><td>Chat connection state without secrets: audience and key set, last verified or refused event</td></tr><tr><td><code>POST /chat/events</code></td><td>Google-signed JWT, verified against the audience</td><td>Google Chat events — point the Chat app here. Refuses everything until the audience is set</td></tr><tr><td><code>POST /tick</code> ✱</td><td>Bearer tick token (open until one exists)</td><td>Advance the scheduler from an external cron (scale-to-zero)</td></tr><tr><td><code>GET /export?standupId=N&amp;days=D</code> ✱</td><td>Bearer export token (404 until one exists)</td><td>CSV, <code>D</code> clamped to 1–365</td></tr><tr><td><code>GET /app[/…]</code></td><td>Session cookie, or the operator token entered on the sign-in page</td><td>The <a href="./web-app.html">web app</a>, including the guided setup at <code>/app/setup</code> and the personal page at <code>/app/me</code></td></tr><tr><td><code>/api/v1/…</code> (300 requests a minute)</td><td>Session cookie, or bearer operator token; <code>auth/methods</code> and <code>openapi.json</code> are public</td><td>The <a href="./api.html">JSON API</a>; OpenAPI 3.1 at <code>GET /api/v1/openapi.json</code></td></tr><tr><td><code>/mcp</code> ✱</td><td>Bearer MCP token (503 while switched off; browser <code>Origin</code> refused)</td><td><a href="./mcp.html">Model Context Protocol</a> for Claude Code and other assistants</td></tr><tr><td><code>GET /auth/google</code>, <code>GET /auth/callback</code>, <code>POST /auth/logout</code> ✱</td><td>OAuth state nonce</td><td>Google sign-in</td></tr><tr><td><code>GET /auth/saml</code>, <code>POST /auth/saml/acs</code>, <code>GET /auth/saml/metadata</code> ✱</td><td>Signed assertions</td><td>SAML sign-in and SP metadata (404 until the IdP is configured)</td></tr><tr><td><code>/scim/v2/ServiceProviderConfig</code>, <code>/scim/v2/Users[…]</code> ✱</td><td>Bearer SCIM token (404 until one exists)</td><td><a href="./enterprise-sso.html#scim-provisioning">SCIM 2.0</a></td></tr></tbody></table><h2 id="outbound-webhooks" tabindex="-1">Outbound webhooks <a class="header-anchor" href="#outbound-webhooks" aria-label="Permalink to &quot;Outbound webhooks&quot;">​</a></h2><p>Give a standup a <strong>Webhook URL</strong> (Standup › Settings › Integrations) and AsyncUp POSTs JSON to it as things happen — the cheap path into Sheets (Apps Script), Zapier/n8n, or your own service:</p><table tabindex="0"><thead><tr><th>Event</th><th>When</th><th>Body</th></tr></thead><tbody><tr><td><code>submission</code></td><td>Every submission and edit</td><td><code>standup</code>, <code>date</code>, <code>user</code>, <code>answers</code>, <code>mood</code>, <code>late</code>, <code>edited</code></td></tr><tr><td><code>wrap_up</code></td><td>The run closes</td><td><code>standup</code>, <code>date</code>, <code>summary</code> (same numbers as the posted wrap-up)</td></tr><tr><td><code>schedule_change</code></td><td>Someone&#39;s week or days off change</td><td>person, summary, who, channel — see <a href="./schedules.html#integrations">Personal schedules</a></td></tr><tr><td><code>time_off_request</code></td><td>A request needs approval</td><td>person, dates, working, reason, request ids</td></tr><tr><td><code>test</code></td><td><strong>Send test</strong> in the standup&#39;s settings</td><td><code>standup</code></td></tr></tbody></table><p>Deliveries time out after 5 s and failures are only logged — a dead webhook never breaks the standup.</p><p>Every delivery is signed: the <code>X-AsyncUp-Signature</code> header carries <code>sha256=&lt;hex&gt;</code>, the HMAC-SHA256 of the raw request body with the standup&#39;s signing secret. Copy it from the standup&#39;s <strong>Settings → Outbound webhook → Show signing secret</strong> (admins and that standup&#39;s managers), or fetch it with <code>GET /api/v1/standups/:id/webhook/secret</code>. It is derived from <code>SECRET_KEY</code> and the standup&#39;s id, so it changes only when <code>SECRET_KEY</code> does.</p><p>Verify it in your receiver and reject anything that doesn&#39;t match:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> expected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sha256=&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crypto.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createHmac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sha256&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SECRET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rawBody).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">digest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hex&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">crypto.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timingSafeEqual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(header), Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(expected));</span></span></code></pre></div><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>All state — standups, participants, admins, runs, submissions, blockers, app settings — lives either in a single SQLite file (<code>DB_PATH</code>, the default) or in your own PostgreSQL (<code>DATABASE_URL</code>). Schema migrations run automatically on startup in both modes. Backups and upgrades: <a href="./operations.html">Operations</a>.</p><blockquote><p><strong>Managed Postgres TLS:</strong> RDS / Cloud SQL / Neon / Supabase present a certificate signed by their own CA. AsyncUp treats <code>sslmode=require</code> as &quot;encrypt but don&#39;t verify the cert&quot; (the libpq default every other client uses), so <code>DATABASE_URL=…?sslmode=require</code> connects out of the box. For strict verification set <code>DB_SSL=verify-full</code> and point <code>DB_SSL_CA</code> at the provider&#39;s CA bundle.</p></blockquote><p>Stored secrets are encrypted, so backups are safe to ship off-box as long as <code>SECRET_KEY</code> stays out of them. Graceful shutdown on SIGTERM included.</p>`,24)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
